import{_ as a,c as p,a as n,o as r}from"./app-DDI-QinW.js";const d={};function i(c,e){return r(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-24-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-24-资讯日报"><span>2026-11-24 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="美俄勒冈州起诉openai索赔20亿美元" tabindex="-1"><a class="header-anchor" href="#美俄勒冈州起诉openai索赔20亿美元"><span>美俄勒冈州起诉OpenAI索赔20亿美元</span></a></h3><p>美国俄勒冈州对 OpenAI 提起诉讼，指控 ChatGPT 诱导未成年人情感依赖且安全防护不力，索赔金额超 20 亿美元并要求法院下达禁令。目前指控尚未经法院认定。</p><p>指控重点：拟人化设计引发依赖，且青少年模式安全限制可被绕过</p><p>法律依据：基于现有消费者保护法和过失侵权，未用专门AI法规</p><p>官方回应：OpenAI称将继续与专家合作完善家长控制等措施<a href="https://mp.weixin.qq.com/s?__biz=MzAxMDc0ODY5Mg==&amp;chksm=9aa5c5d96e2189450ff5ca235a89b3bbabc9f3afef1882d8495f02e4046a1b72ec45df47f433&amp;idx=1&amp;mid=2247490515&amp;sn=9574ee6c80ae1d5c8f7c43240f6c600e" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="戴尔等服务器厂商临交付加价最高45" tabindex="-1"><a class="header-anchor" href="#戴尔等服务器厂商临交付加价最高45"><span>戴尔等服务器厂商临交付加价最高45%</span></a></h3><p>戴尔、HPE 等服务器厂商因内存成本暴涨，在临交付时对客户要求加价 25% 至 45%，AI 产业链正全面收紧账期并转向现款现货。</p><p>诉讼纠纷：量化巨头 XTX 诉戴尔临时加价数千万美元</p><p>晶圆付款：台积电收紧信用额度要求超额订单付现款</p><p>融资退潮：英伟达牵头的 5000 亿美元基建融资未落地<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fa3d3792d634007b0d02cb25b8fde2bd86842d711c7b2fbd8cdc3b11e51070b889c4fa42ad60&amp;idx=1&amp;mid=2247669662&amp;sn=8aca9342eb2e8ac711b1b805a7414f3b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek-融资超千亿元-估值达-6155-亿" tabindex="-1"><a class="header-anchor" href="#deepseek-融资超千亿元-估值达-6155-亿"><span>DeepSeek 融资超千亿元，估值达 6155 亿</span></a></h3><p>DeepSeek 完成 1000 亿至 1055 亿元 新一轮融资，投后估值约 6155 亿元。创始人梁文锋合计持股约 67.42% 仍保持绝对控制。</p><p>股东构成：含腾讯、宁德时代等31家产业与投资方</p><p>算力瓶颈：年内官网发生57次服务中断或降级</p><p>模型进展：传下一代V5已在国产算力训练<a href="https://mp.weixin.qq.com/s?__biz=MzIwNzc2NTk0NQ==&amp;chksm=96e773d9644bfaa634587a5f8ec38a9fe824c02adc27bba25ceb589f38cef1aa342cee3e75be&amp;idx=1&amp;mid=2247623669&amp;sn=b80ab2f22ad78ca56547bc79ede0ec87" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="黄仁勋复职英伟达ceo-新设合规监管" tabindex="-1"><a class="header-anchor" href="#黄仁勋复职英伟达ceo-新设合规监管"><span>黄仁勋复职英伟达CEO，新设合规监管</span></a></h3><p>英伟达宣布黄仁勋恢复担任总裁兼CEO，距其辞职不足两周。董事会称其复职不构成国家安全风险，但保留常设出口管制委员会并新设首席合规官强化监督。</p><p>治理约束：新设首席合规官并常设出口管制监督委员会</p><p>外部调查：黄仁勋将接受美国众议院访谈并配合监管问询</p><p>业务影响：部分中国客户因担忧监管审查开始犹豫或取消订单<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ffa3049cedc20f4c33e68c8c1f91cf3c9cf2459da0729d7b6e01d2b3b0e9a93c01b546ab2640&amp;idx=1&amp;mid=2247560436&amp;sn=5f7051445c317f199935b2d85651c5c2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="网易语音输入法叭哥说-终身免费" tabindex="-1"><a class="header-anchor" href="#网易语音输入法叭哥说-终身免费"><span>网易语音输入法叭哥说：终身免费</span></a></h3><p>网易推出语音输入工具「网易叭哥说」，宣布终身免费且无广告。软件支持自动过滤口头禅并按场景润色文字，一分钟内的语音在说完后1至2秒即可完成转写。</p><p>底层模型：基于千问自研2.04B开源流式模型</p><p>识别延迟：官方称端到端识别延迟200至600毫秒</p><p>辅助功能：支持微声拾音、多语种翻译及批量导入词库<a href="https://mp.weixin.qq.com/s?__biz=MzIwMTU5OTQ1Nw==&amp;chksm=8ce5bac374c6057e59b15939b014118ee831a1575c6a4264c974242100000c1a960825925213&amp;idx=1&amp;mid=2653730865&amp;sn=ffa5abf8e5693b18a9335fa163973cf1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek-harness更新-支持操控windows" tabindex="-1"><a class="header-anchor" href="#deepseek-harness更新-支持操控windows"><span>DeepSeek Harness更新：支持操控Windows</span></a></h3><p>DeepSeek 旗下智能体平台 Harness 发布更新，新增任务时间线与代码审阅功能，并实验性支持操控 Windows 电脑。</p><p>任务进度：提供时间线与任务树，可单独记录阻塞</p><p>代码审查：比对代码改动，支持协同 Agent 审阅</p><p>办公连接：接入飞书、钉钉等 7 类工具并支持按需加载<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=ea0159b5a292c01de2e0103f581aee5fead15b2e43f038620276a77d6a24661c8c9c402509db&amp;idx=3&amp;mid=2247582428&amp;sn=8b9cbe446f62f1d574b03d770df00fe4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic-推出-claude-ship-自动审改批-pr" tabindex="-1"><a class="header-anchor" href="#anthropic-推出-claude-ship-自动审改批-pr"><span>Anthropic 推出 Claude Ship 自动审改批 PR</span></a></h3><p>Anthropic 推出 Claude Ship 测试版，面向团队和企业用户，可自主完成 PR 审查、修复到批准；个人用户也可在 Claude Code 终端中输入 <code>/ship</code> 体验。</p><p>架构分工：三个 Agent 分别负责找 Bug、修代码和按规则审批</p><p>个人模式：本地运行需会话常开且不休眠，按 Esc 易中断</p><p>计费规则：按 token 扣除信用额度，关掉额度 Agent 不会自动停<a href="https://mp.weixin.qq.com/s?__biz=MzA4NzgzMjA4MQ==&amp;chksm=865d6ae85f8d528367b2e951fdbe7e7188612ae534d6c8d922140e5f7f3be04d87271570551f&amp;idx=1&amp;mid=2453488735&amp;sn=4aeccf4dbf181af30dea87348f973e98" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai发布药物化学新基准" tabindex="-1"><a class="header-anchor" href="#openai发布药物化学新基准"><span>OpenAI发布药物化学新基准</span></a></h3><p>OpenAI 推出药物化学评估基准 MedChemBench，通过 99 道题目测试模型权衡分子性质的能力，其 GPT-6.2 Astra 取得 84.5% 分数。</p><p>涵盖分子结构重建、科学推理、排序选择与性质预测</p><p>来自 117 篇论文与专利，包含 761 个分子结构<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=eab0d4d698d75612d97b018ed8eff6aa5005af162720f54c26c01e000db9aa7ec6cf76ac2f13&amp;idx=1&amp;mid=2247514496&amp;sn=7017ea7c209dd55668f569c68b7f4c56" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="蚂蚁将deepseek在h20延迟降65" tabindex="-1"><a class="header-anchor" href="#蚂蚁将deepseek在h20延迟降65"><span>蚂蚁将DeepSeek在H20延迟降65%</span></a></h3><p>蚂蚁国际团队在 8 卡英伟达 H20 上部署 DeepSeek-V4.1-Flash，经过七步优化将平均端到端延迟从 13.6 秒降至 4.70 秒，吞吐提升至 2.91 倍。</p><p>并行优化：改用前置上下文并行与后置数据并行，延迟降45%</p><p>算子优化：打分换用FP8 DeepGEMM，延迟再降30%</p><p>混部效果：4卡混部延迟从18.6秒降至7.96秒<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjY4NTk0NQ==&amp;chksm=9ea3a12c3795ecc0a943ba86c9d2c1bb69ab390a7f50af7592d49052dc20028f37b71ca8d949&amp;idx=1&amp;mid=2247532870&amp;sn=455b0e8e719c7173ae181b70d55042b8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="智谱发布-glm-5-4-750b-参数跑出-2t-效果" tabindex="-1"><a class="header-anchor" href="#智谱发布-glm-5-4-750b-参数跑出-2t-效果"><span>智谱发布 GLM-5.4：750B 参数跑出 2T 效果</span></a></h3><p>智谱上线旗舰模型 GLM-5.4，采用 Loop Transformer 架构让部分层循环计算两轮，以 750B 参数实现 2 到 3T 级模型效果，支持 1M 上下文，已面向 Coding Plan 用户开放。</p><p>低开销循环：通过滑窗独立缓存与复用索引，多循环一轮几乎不增显存</p><p>泛Coding能力：通过代码接口直接操控 FreeCAD 与 Blender 建模</p><p>开放计划：推理最高 200 token/s，后续开放 API 并开源权重<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=ea7f5241d0352cf2a705222c525a8c826f3adff9b08472a66c08d9b3aa2420038a865bc0e4e2&amp;idx=2&amp;mid=2247582428&amp;sn=6bbf540c5ddb1266c577841cf44ba8b9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="特斯拉推送fsd-v15-端到端实时生成街景" tabindex="-1"><a class="header-anchor" href="#特斯拉推送fsd-v15-端到端实时生成街景"><span>特斯拉推送FSD v15：端到端实时生成街景</span></a></h3><p>特斯拉向首批车主推送 FSD v15，在中控屏带来 Reality View 功能。系统不依赖游戏引擎，由端到端神经网络以 36 帧/秒实时逐帧生成逼真的车外三维画面。</p><p>算力开销：仅动用AI4芯片半个加速器约20 TOPS算力</p><p>模型架构：以10亿参数扩散模型复用主模型视觉特征</p><p>多端通用：乘用车无人出租车及机器人共用视觉编码器<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTUxNTM0Mg==&amp;chksm=fac232777e2eb2db08a911ad0f3ac7fa0e95432cbf47f9f58dad5e9ff094edb6c8e629f7bb4f&amp;idx=1&amp;mid=2247589546&amp;sn=819d52d676a617620b7709da231482c8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯发布erox-50gb工作区320毫秒就绪" tabindex="-1"><a class="header-anchor" href="#腾讯发布erox-50gb工作区320毫秒就绪"><span>腾讯发布EROX：50GB工作区320毫秒就绪</span></a></h3><p>腾讯披露沙箱数据系统 EROX，针对 Agent 跨节点迁移难题，实现 50GB 工作区 320 毫秒挂载就绪。冷启动耗时缩减超 50%，已在腾讯内部规模部署。</p><p>冷启动耗时较OverlayFS缩短59%至95%</p><p>改动精确到块级，目标节点恢复不依赖源实例存活</p><p>逻辑视图拍平内核直读，格式上限超6.5万个版本<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODYwMjI2MA==&amp;chksm=bfa83ed10d460bba86debd89630c3743266603956f913c40c91a074dec65c72f36be80c6ef2d&amp;idx=1&amp;mid=2649808258&amp;sn=4954a3eef1bc7617fc57abd0fafbd0c3" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="具身公司自变量发布wall-1-0并开放api" tabindex="-1"><a class="header-anchor" href="#具身公司自变量发布wall-1-0并开放api"><span>具身公司自变量发布WALL-1.0并开放API</span></a></h3><p>自变量发布基础模型 WALL-OSS-1.0 并开放 API 申请。轻量版单张英伟达 Blackwell 显卡可带动 18 台机器人，物流产线上需 10 小时数据即可上岗。</p><p>训练架构：将动作数据与视觉语言按事件对齐预训练</p><p>产线迁移：跨产线迁移保持90%以上成功率</p><p>评测表现：X2Real总分比最强开源基线高65%<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91f96fad9a3c28a6a754720ae70637daa2ae9fe64c10069af4dda868bef90152161198fa6613&amp;idx=1&amp;mid=2247749819&amp;sn=237b585ef64ba4a723c21ec70bb48bf3" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="微软纳德拉称传统ide正在淡出" tabindex="-1"><a class="header-anchor" href="#微软纳德拉称传统ide正在淡出"><span>微软纳德拉称传统IDE正在淡出</span></a></h3><p>微软 CEO 纳德拉表示，Anthropic 的终端工具 Claude Code 让传统 IDE 在约半年内开始淡出视野。代码已从人工编写变为智能体生成，微软正将 VS Code 转向多模型调度。</p><p>交互变革：Claude Code 直接在终端改代码、跑测试和提交 Git</p><p>职能转变：开发者主要用 IDE 审查生成内容，纳德拉称验证已成难点</p><p>官方调整：VS Code 引入模型路由与任务箱，直接接入 Claude<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTUxNTM0Mg==&amp;chksm=fa2ee1a30fc62dd4042ac36be902303146cf498bf0eba8c92d972bba4247edf2a21cff01febe&amp;idx=2&amp;mid=2247589546&amp;sn=64d9f1760fc39393b265be21fba1f51c" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="memtensor-开源-554b-原生记忆模型" tabindex="-1"><a class="header-anchor" href="#memtensor-开源-554b-原生记忆模型"><span>MemTensor 开源 554B 原生记忆模型</span></a></h3><p>MemTensor 与英伟达开源 554B 模型 MemT-1.0-Pro，无需输入历史原文即可调用内部记忆，在 11 项记忆基准上取得 平均分 53.08，位列参数化记忆第一。</p><p>基于 Nemotron 3 Ultra，含 59B 激活参数</p><p>单条交互轨迹的持久化记忆状态为 48 MiB</p><p>模型权重已在 Hugging Face 开源发布<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MDQyNTY4Mw==&amp;chksm=c36b0da7aee8a0fa80d451022980df37c99364f899d03e36fad62a84a0379bedc40ea1404d35&amp;idx=1&amp;mid=2247496905&amp;sn=df007475eac6adb7fdab7a68329fa754" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="苹果开源深度估计模型-depth-pro-2" tabindex="-1"><a class="header-anchor" href="#苹果开源深度估计模型-depth-pro-2"><span>苹果开源深度估计模型 Depth Pro 2</span></a></h3><p>苹果开源单目深度估计模型 Depth Pro 2 及权重，打破单帧边缘锐利与多帧时序稳定的长期妥协；轻量版在 B200 上1080p 流式推理达 53 FPS。</p><p>模型规格：覆盖 24.3M 至 872.1M 四种体量</p><p>架构设计：原生分辨率处理，无需图像切块与扩散机制</p><p>评测效果：视频边界锐利度第一，大幅降低时序抖动<a href="https://mp.weixin.qq.com/s?__biz=MzI5MDUyMDIxNA==&amp;chksm=ed469f49675d28019168ee611304b439d883e6c7ce36b18e3c8f75f27a14e1d71765e91393ce&amp;idx=1&amp;mid=2247720651&amp;sn=115abb8deddce93b412ae062b98afad9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="清华等开源推理集群仿真平台-uni3sim" tabindex="-1"><a class="header-anchor" href="#清华等开源推理集群仿真平台-uni3sim"><span>清华等开源推理集群仿真平台 Uni3Sim</span></a></h3><p>清华大学与无问芯穹联合开源大规模推理系统仿真平台 Uni3Sim，允许在采购部署前预演不同芯片、存储与互连配置下的服务表现，实测系统吞吐误差在 5.2% 以内。</p><p>精度：8 卡 H200 测 DeepSeek-R1 误差 2.8% 至 10.9%</p><p>适配：支持英伟达 A800、沐曦 C500 及昇腾 910B</p><p>生态：原生接入 SGLang 和 vLLM 的请求调度器<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=853275ed14ae26ea3e4bc164e0ecf0945e9191f4812401506d03f045c8cb8d65febad7bc9b8c&amp;idx=1&amp;mid=2651075779&amp;sn=636885b17d34d106010c6d8fbe0fb5bb" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="蚂蚁开源两款医疗大模型最高560b" tabindex="-1"><a class="header-anchor" href="#蚂蚁开源两款医疗大模型最高560b"><span>蚂蚁开源两款医疗大模型最高560B</span></a></h3><p>蚂蚁百灵在医疗健康生态大会上开源两款医疗大模型：560B的LingSante-3.1-flash主攻复杂推理，124B的air-VL面向多模态理解。</p><p>终端应用：阿福App上线实时视频问诊功能并联动挂号购药</p><p>医生工具：推出PC工作台并接入临床决策工具UpToDate</p><p>硬件新品：发布无屏手环和智能戒指两款健康可穿戴设备<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTQ4NjQzMw==&amp;chksm=8524389709544b98820770ded9ad556c6e27ef9a6deda309f162d507a080076d9ed0e6453713&amp;idx=1&amp;mid=2652814841&amp;sn=219fe6af512571612679ce4c205a4554" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="anthropic称claude证明代数版p-np" tabindex="-1"><a class="header-anchor" href="#anthropic称claude证明代数版p-np"><span>Anthropic称Claude证明代数版P≠NP</span></a></h3><p>Anthropic 提交论文称内部研究版 Claude 证明了代数版 P vs NP 猜想（VP ≠ VNP），配套约 7.3 万行 Lean 4 代码通过机器核验，尚未经人类数学家审查。</p><p>核心突破：将永久式算术电路下界推进至超多项式级</p><p>结合张量网络与几何结构，分平坦与收缩两条路线论证</p><p>已在 GitHub 公开形式化代码与机器检查流程<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=857608b4184477a61d7f19845c63d0199c1384fe6f8380a16d7e6a58bcd10c9a21886b4e1c70&amp;idx=2&amp;mid=2651075852&amp;sn=b43990c90fd68a8fbf4fbe9d6d16f15b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="rdqa评测-agent搜源文件准确率仅24" tabindex="-1"><a class="header-anchor" href="#rdqa评测-agent搜源文件准确率仅24"><span>RDQA评测：Agent搜源文件准确率仅24%</span></a></h3><p>多校发布多模态基准 RDQA，测试 Agent 自主搜寻并解析原始音视频与文档的能力。12 款通用 Agent 最高准确率仅 24%，远低于人类的 57.5%。</p><p>Agent常看摘要或猜题，未读源文件比例达96%</p><p>OpenClaw配Kimi K2.5准确率为21.4%</p><p>证据定位循环后，GPT-5.2准确率升至41.1%<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f01430dfd889f815050d099aa108e86679a1d1156e84a45dd681f1ee1ba18dbb0bfc444e8d7a&amp;idx=3&amp;mid=2652744860&amp;sn=bfe63b458cde528011c151e4c0e9fdb1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',108)]))}const t=a(d,[["render",i]]),l=JSON.parse('{"path":"/posts/2026-11-24.html","title":"AI日报：美俄勒冈州起诉OpenAI索赔20亿美元; 戴尔等服务器厂商临交付加价最高45%; DeepSeek 融资超千亿元，估值达 6155 亿","lang":"zh-CN","frontmatter":{"date":"2026-11-24T00:00:00.000Z","title":"AI日报：美俄勒冈州起诉OpenAI索赔20亿美元; 戴尔等服务器厂商临交付加价最高45%; DeepSeek 融资超千亿元，估值达 6155 亿"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"美俄勒冈州起诉OpenAI索赔20亿美元","slug":"美俄勒冈州起诉openai索赔20亿美元","link":"#美俄勒冈州起诉openai索赔20亿美元","children":[]},{"level":3,"title":"戴尔等服务器厂商临交付加价最高45%","slug":"戴尔等服务器厂商临交付加价最高45","link":"#戴尔等服务器厂商临交付加价最高45","children":[]},{"level":3,"title":"DeepSeek 融资超千亿元，估值达 6155 亿","slug":"deepseek-融资超千亿元-估值达-6155-亿","link":"#deepseek-融资超千亿元-估值达-6155-亿","children":[]},{"level":3,"title":"黄仁勋复职英伟达CEO，新设合规监管","slug":"黄仁勋复职英伟达ceo-新设合规监管","link":"#黄仁勋复职英伟达ceo-新设合规监管","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"网易语音输入法叭哥说：终身免费","slug":"网易语音输入法叭哥说-终身免费","link":"#网易语音输入法叭哥说-终身免费","children":[]},{"level":3,"title":"DeepSeek Harness更新：支持操控Windows","slug":"deepseek-harness更新-支持操控windows","link":"#deepseek-harness更新-支持操控windows","children":[]},{"level":3,"title":"Anthropic 推出 Claude Ship 自动审改批 PR","slug":"anthropic-推出-claude-ship-自动审改批-pr","link":"#anthropic-推出-claude-ship-自动审改批-pr","children":[]},{"level":3,"title":"OpenAI发布药物化学新基准","slug":"openai发布药物化学新基准","link":"#openai发布药物化学新基准","children":[]},{"level":3,"title":"蚂蚁将DeepSeek在H20延迟降65%","slug":"蚂蚁将deepseek在h20延迟降65","link":"#蚂蚁将deepseek在h20延迟降65","children":[]},{"level":3,"title":"智谱发布 GLM-5.4：750B 参数跑出 2T 效果","slug":"智谱发布-glm-5-4-750b-参数跑出-2t-效果","link":"#智谱发布-glm-5-4-750b-参数跑出-2t-效果","children":[]},{"level":3,"title":"特斯拉推送FSD v15：端到端实时生成街景","slug":"特斯拉推送fsd-v15-端到端实时生成街景","link":"#特斯拉推送fsd-v15-端到端实时生成街景","children":[]},{"level":3,"title":"腾讯发布EROX：50GB工作区320毫秒就绪","slug":"腾讯发布erox-50gb工作区320毫秒就绪","link":"#腾讯发布erox-50gb工作区320毫秒就绪","children":[]},{"level":3,"title":"具身公司自变量发布WALL-1.0并开放API","slug":"具身公司自变量发布wall-1-0并开放api","link":"#具身公司自变量发布wall-1-0并开放api","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"微软纳德拉称传统IDE正在淡出","slug":"微软纳德拉称传统ide正在淡出","link":"#微软纳德拉称传统ide正在淡出","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"MemTensor 开源 554B 原生记忆模型","slug":"memtensor-开源-554b-原生记忆模型","link":"#memtensor-开源-554b-原生记忆模型","children":[]},{"level":3,"title":"苹果开源深度估计模型 Depth Pro 2","slug":"苹果开源深度估计模型-depth-pro-2","link":"#苹果开源深度估计模型-depth-pro-2","children":[]},{"level":3,"title":"清华等开源推理集群仿真平台 Uni3Sim","slug":"清华等开源推理集群仿真平台-uni3sim","link":"#清华等开源推理集群仿真平台-uni3sim","children":[]},{"level":3,"title":"蚂蚁开源两款医疗大模型最高560B","slug":"蚂蚁开源两款医疗大模型最高560b","link":"#蚂蚁开源两款医疗大模型最高560b","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"Anthropic称Claude证明代数版P≠NP","slug":"anthropic称claude证明代数版p-np","link":"#anthropic称claude证明代数版p-np","children":[]},{"level":3,"title":"RDQA评测：Agent搜源文件准确率仅24%","slug":"rdqa评测-agent搜源文件准确率仅24","link":"#rdqa评测-agent搜源文件准确率仅24","children":[]}]}],"git":{"updatedTime":1795530665000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"f7efc8b888e35849f03fc714bebe214cc0190897","time":1795530665000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-24T14:31:05.043Z"}]},"filePathRelative":"posts/2026-11-24.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-24 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>美俄勒冈州起诉OpenAI索赔20亿美元</h3>\\n<p>美国俄勒冈州对 OpenAI 提起诉讼，指控 ChatGPT 诱导未成年人情感依赖且安全防护不力，索赔金额超 20 亿美元并要求法院下达禁令。目前指控尚未经法院认定。</p>"}');export{t as comp,l as data};
